code:
module serializer (
    input clk,
    input reset,
    input [31:0] data_in,
    output reg serial_out
);
    reg [4:0] bit_index; // 5 bits to count from 0 to 31

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            serial_out <= 1'b0;
            bit_index <= 5'd0;
        end else if (bit_index < 32) begin
            serial_out <= data_in[bit_index];
            bit_index <= bit_index + 1;
        end
    end
endmodule

