module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);

    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;
    reg [1:0] state, next_state;
    reg [3:0] bit_count;
    reg [10:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [15:0] baud_counter; // for timing control

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            tx <= 1; // Idle state for UART is high
            busy <= 0;
            baud_counter <= 0;
        end else begin
            state <= next_state;
            if (baud_counter < 5208) // 9600 baud rate at 50MHz clock
                baud_counter <= baud_counter + 1;
            else
                baud_counter <= 0;
        end
    end

    always @(state or start or bit_count) begin
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = START;
                    busy = 1;
                end else begin
                    next_state = IDLE;
                end
            end
            START: begin
                next_state = DATA;
                shift_reg = {data_in, 1'b0}; // Add start bit
                bit_count = 0;
                tx = 0; // Transmit start bit (low)
            end
            DATA: begin
                if (bit_count < 8) begin
                    if (baud_counter == 0) begin
                        tx = shift_reg[bit_count]; // Transmit data bits
                        bit_count = bit_count + 1;
                    end
                    next_state = DATA;
                end else begin
                    next_state = STOP;
                end
            end
            STOP: begin
                if (baud_counter == 0) begin
                    tx = 1; // Transmit stop bit (high)
                    busy = 0;
                    next_state = IDLE;
                end else begin
                    next_state = STOP;
                end
            end
            default: next_state = IDLE;
        endcase
    end
endmodule

