module serializer (  
    input clk,  
    input rst,  
    input [7:0] parallel_in,  
    input start,  
    output reg serial_out,  
    output reg valid  
);  
    reg [2:0] bit_index;  
    reg [7:0] data;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            bit_index <= 3'b000;  
            serial_out <= 1'b0;  
            valid <= 1'b0;  
        end else if (start) begin  
            data <= parallel_in;  
            bit_index <= 3'b000;  
            valid <= 1'b1;  
        end else if (valid) begin  
            serial_out <= data[7 - bit_index];  
            bit_index <= bit_index + 1;  
            if (bit_index == 3'b111) begin  
                valid <= 1'b0;  
            end  
        end  
    end  
endmodule

