module divider_8bit (  
    input clk,  
    input start,  
    input [7:0] numerator,  
    input [7:0] denominator,  
    output reg [7:0] quotient,  
    output reg [7:0] remainder,  
    output reg done  
);  
    reg [7:0] num;  
    reg [7:0] den;  
    reg [3:0] count;  
    reg processing;  

    always @(posedge clk) begin  
        if (start) begin  
            num <= numerator;  
            den <= denominator;  
            quotient <= 0;  
            remainder <= 0;  
            count <= 8;  
            processing <= 1;  
            done <= 0;  
        end else if (processing) begin  
            if (count > 0) begin  
                remainder <= {remainder[6:0], num[7]};  
                num <= {num[6:0], 1'b0};  
                if (remainder >= den) begin  
                    remainder <= remainder - den;  
                    quotient <= {quotient[6:0], 1'b1};  
                end else begin  
                    quotient <= {quotient[6:0], 1'b0};  
                end  
                count <= count - 1;  
            end else begin  
                processing <= 0;  
                done <= 1;  
            end  
        end  
    end  
endmodule

