module i2c_master (  
    input wire clk,  
    input wire start,  
    input wire [7:0] data,  
    output reg scl,  
    output reg sda,  
    output reg stop  
);  
    reg [3:0] state;  
    parameter IDLE = 0, START = 1, SEND = 2, STOP = 3;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                stop <= 0;  
                if (start) begin  
                    sda <= 0; // Start condition  
                    state <= START;  
                end  
            end  
            START: begin  
                scl <= 0;  
                sda <= data[7]; // Send MSB first  
                state <= SEND;  
            end  
            SEND: begin  
                // Shift data out  
                scl <= 1;  
                sda <= data[6];  
                state <= (data[6] == 0) ? STOP : SEND;  
            end  
            STOP: begin  
                scl <= 0;  
                sda <= 1; // Stop condition  
                stop <= 1;  
                state <= IDLE;  
            end  
            default: state <= IDLE;  
        endcase  
    end  
endmodule

