module gpio_controller (
    input wire clk,
    input wire enable,
    input wire [7:0] dir,   // Direction: 1=output, 0=input
    input wire [7:0] data_in, // Data to write to GPIO pins
    output reg [7:0] data_out // Data read from GPIO pins
);
    reg [7:0] gpio_reg; // Register to hold GPIO state

    always @(posedge clk) begin
        if (enable) begin
            // Write to GPIO pins if direction is output
            gpio_reg <= (dir) ? data_in : gpio_reg;
            // Read from GPIO pins if direction is input
            data_out <= (dir) ? 8'bz : gpio_reg;
        end
    end
endmodule

