module fractional_n_pll(  
    input wire clk_in,  
    input wire reset,  
    input wire [3:0] control_signal, // Control signal to adjust division ratio  
    output reg clk_out  
);  
    reg [3:0] div_ratio;  
    reg [7:0] counter;  
    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            clk_out <= 0;  
            div_ratio <= 1;  
        end else begin  
            div_ratio <= control_signal + 1; // Calculate division ratio based on control signal  
            if (counter == div_ratio - 1) begin  
                clk_out <= ~clk_out;  
                counter <= 0;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

