module PLL (  
    input wire clk_input,  
    input wire reset,  
    output reg clk_output  
);  

    reg [3:0] phase_counter;  
    reg vco_output;  
    reg [3:0] filter_output;  

    always @(posedge clk_input or posedge reset) begin  
        if (reset) begin  
            phase_counter <= 0;  
            vco_output <= 0;  
            filter_output <= 0;  
            clk_output <= 0;  
        end else begin  
            phase_counter <= phase_counter + 1;  
            filter_output <= (filter_output + 1) >> 1; // simple low-pass filter  
            vco_output <= (filter_output > 2) ? 1 : 0; // VCO frequency control  
            clk_output <= vco_output;  
        end  
    end  
endmodule

