module serializer_32bit(  
    input wire clk,  
    input wire reset,  
    input wire [31:0] data_in,  
    input wire valid,  
    output reg serialized_out,  
    output reg done  
);  
    reg [5:0] bit_count;  
    reg [31:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_count <= 0;  
            serialized_out <= 0;  
            done <= 0;  
            shift_reg <= 0;  
        end else if (valid && bit_count == 0) begin  
            shift_reg <= data_in;  
            bit_count <= 32;  
            done <= 0;  
        end else if (bit_count > 0) begin  
            serialized_out <= shift_reg[31];  
            shift_reg <= {shift_reg[30:0], 1'b0};  
            bit_count <= bit_count - 1;  
            if (bit_count == 1) begin  
                done <= 1;  
            end  
        end  
    end  
endmodule

