module voltage_regulator(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire [7:0] ref_voltage,  
    input wire [7:0] control_signal,  
    output reg [7:0] output_voltage  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, ENABLED = 2'b01, DISABLED = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            output_voltage <= 8'b0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (enable)  
                        state <= ENABLED;  
                end  
                ENABLED: begin  
                    output_voltage <= ref_voltage + control_signal;  
                    if (!enable)  
                        state <= DISABLED;  
                end  
                DISABLED: begin  
                    output_voltage <= 8'b0;  
                    if (enable)  
                        state <= ENABLED;  
                end  
                default: state <= IDLE;  
            endcase  
        end  
    end  
endmodule

