module pll (
    input clk_in,
    input reset,
    output reg clk_out
);

// Parameters for PLL
parameter N = 4; // VCO multiplier
parameter M = 1; // Phase comparator division factor

reg [N-1:0] vco_counter = 0;
reg [M-1:0] phase_error = 0;

always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        vco_counter <= 0;
        clk_out <= 0;
    end else begin
        // Phase comparator and feedback
        phase_error <= vco_counter - phase_error;

        // Simple loop filter (integrator)
        if (phase_error[N-1] == 0) begin
            vco_counter <= vco_counter + 1;
        end else begin
            vco_counter <= vco_counter - 1;
        end

        // Generate output clock
        if (vco_counter >= N) begin
            clk_out <= ~clk_out;
            vco_counter <= 0;
        end
    end
end

endmodule

