module linked_list_traversal(
    input clk,
    input rst,
    input valid,
    input [7:0] data_in,
    output reg [7:0] current_data,
    output reg done
);
    reg [3:0] current_node; // 4-bit to address nodes (up to 15 nodes)
    reg [3:0] next_node [0:15]; // Next pointers for each node
    reg [7:0] data_array [0:15]; // Data for each node

    initial begin
        // Sample initialization of the linked list
        next_node[0] = 1;
        next_node[1] = 2;
        next_node[2] = 3;
        next_node[3] = 4;
        next_node[4] = 5;
        next_node[5] = 15; // End of list
        next_node[6] = 15;
        next_node[7] = 15;
        next_node[8] = 15;
        next_node[9] = 15;
        next_node[10] = 15;
        next_node[11] = 15;
        next_node[12] = 15;
        next_node[13] = 15;
        next_node[14] = 15;
        next_node[15] = 15;

        data_array[0] = 8'h01;
        data_array[1] = 8'h02;
        data_array[2] = 8'h03;
        data_array[3] = 8'h04;
        data_array[4] = 8'h05;
        data_array[5] = 8'hFF; // End of data
        data_array[6] = 8'hFF;
        data_array[7] = 8'hFF;
        data_array[8] = 8'hFF;
        data_array[9] = 8'hFF;
        data_array[10] = 8'hFF;
        data_array[11] = 8'hFF;
        data_array[12] = 8'hFF;
        data_array[13] = 8'hFF;
        data_array[14] = 8'hFF;
        data_array[15] = 8'hFF;

        current_node = 0;
        done = 0;
        current_data = 8'b0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_node <= 0;
            done <= 0;
            current_data <= 8'b0;
        end else if (valid) begin
            if (current_node < 15) begin
                current_data <= data_array[current_node];
                current_node <= next_node[current_node];
            end else begin
                done <= 1;
            end
        end
    end
endmodule

