module fir_filter (
    input wire clk,
    input wire reset,
    input wire [15:0] data_in,
    output wire [31:0] data_out
);
    reg [15:0] x [0:31]; // Input samples
    reg [31:0] h [0:31]; // Filter coefficients
    reg [31:0] y; // Output result
    integer i;

    initial begin
        // Initialize filter coefficients
        h[0] = 16'h0001; h[1] = 16'h0002; h[2] = 16'h0003; h[3] = 16'h0004;
        h[4] = 16'h0005; h[5] = 16'h0006; h[6] = 16'h0007; h[7] = 16'h0008;
        h[8] = 16'h0009; h[9] = 16'h000A; h[10] = 16'h000B; h[11] = 16'h000C;
        h[12] = 16'h000D; h[13] = 16'h000E; h[14] = 16'h000F; h[15] = 16'h0010;
        h[16] = 16'h0011; h[17] = 16'h0012; h[18] = 16'h0013; h[19] = 16'h0014;
        h[20] = 16'h0015; h[21] = 16'h0016; h[22] = 16'h0017; h[23] = 16'h0018;
        h[24] = 16'h0019; h[25] = 16'h001A; h[26] = 16'h001B; h[27] = 16'h001C;
        h[28] = 16'h001D; h[29] = 16'h001E; h[30] = 16'h001F; h[31] = 16'h0020;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 32'b0;
            for (i = 0; i < 32; i = i + 1) begin
                x[i] <= 16'b0;
            end
        end else begin
            // Shift input samples
            for (i = 31; i > 0; i = i - 1) begin
                x[i] <= x[i - 1];
            end
            x[0] <= data_in;

            // Compute output
            y <= 32'b0;
            for (i = 0; i < 32; i = i + 1) begin
                y <= y + (x[i] * h[i]);
            end
        end
    end

    assign data_out = y;

endmodule

