module robot_movement(
    input clk,
    input reset,
    input [1:0] direction, // 00: IDLE, 01: UP, 10: DOWN, 11: LEFT or RIGHT
    output reg [2:0] state // 3 bits to represent IDLE, MOVING_UP, MOVING_DOWN, MOVING_LEFT, MOVING_RIGHT
);
    // State encoding
    parameter IDLE = 3'b000;
    parameter MOVING_UP = 3'b001;
    parameter MOVING_DOWN = 3'b010;
    parameter MOVING_LEFT = 3'b011;
    parameter MOVING_RIGHT = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (direction)
                2'b00: state <= IDLE; // Idle state
                2'b01: state <= MOVING_UP; // Move up
                2'b10: state <= MOVING_DOWN; // Move down
                2'b11: state <= MOVING_LEFT; // Move left or right, can be modified for more directions
                default: state <= IDLE; // Safety default
            endcase
        end
    end
endmodule

