module deserializer_32bit (  
    input wire clk,  
    input wire reset,  
    input wire serial_in,  
    output reg [31:0] parallel_out,  
    output reg valid  
);  
    integer count;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            parallel_out <= 32'b0;  
            count <= 0;  
            valid <= 0;  
        end else begin  
            if (count < 32) begin  
                parallel_out <= {parallel_out[30:0], serial_in};  
                count <= count + 1;  
            end  
            if (count == 31) begin  
                valid <= 1;  
            end  
        end  
    end  
endmodule

