module fractional_n_pll (  
    input wire clk_ref,  
    input wire [15:0] fcw,  
    input wire reset,  
    output reg clk_out  
);  
    reg [15:0] counter;  
    reg [15:0] div_count;  
    reg [15:0] phase_error;  
    reg [15:0] phase_accum;  
    reg [15:0] numerator;  
    reg [15:0] denominator;  
    parameter integer N = 16; // Example value for the PLL's N value

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            phase_accum <= 0;  
            clk_out <= 0;  
        end else begin  
            numerator <= fcw;  
            denominator <= N;  
            phase_accum <= phase_accum + numerator;  
            if (phase_accum >= denominator) begin  
                phase_accum <= phase_accum - denominator;  
                clk_out <= ~clk_out;  
            end  
        end  
    end  
endmodule

