module DVFS_Controller (
    input clk,
    input reset,
    input [2:0] performance_req, // Performance requirement: 0 - 7
    output reg [1:0] voltage_level, // Voltage levels: 00 - 11
    output reg [1:0] frequency_level // Frequency levels: 00 - 11
);

    parameter LOW_VOLTAGE = 2'b00;
    parameter MEDIUM_VOLTAGE = 2'b01;
    parameter HIGH_VOLTAGE = 2'b10;
    parameter MAX_VOLTAGE = 2'b11;

    parameter LOW_FREQ = 2'b00;
    parameter MEDIUM_FREQ = 2'b01;
    parameter HIGH_FREQ = 2'b10;
    parameter MAX_FREQ = 2'b11;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            voltage_level <= LOW_VOLTAGE;
            frequency_level <= LOW_FREQ;
        end else begin
            case (performance_req)
                3'b000: begin
                    voltage_level <= LOW_VOLTAGE;
                    frequency_level <= LOW_FREQ;
                end
                3'b001: begin
                    voltage_level <= LOW_VOLTAGE;
                    frequency_level <= MEDIUM_FREQ;
                end
                3'b010: begin
                    voltage_level <= MEDIUM_VOLTAGE;
                    frequency_level <= MEDIUM_FREQ;
                end
                3'b011: begin
                    voltage_level <= MEDIUM_VOLTAGE;
                    frequency_level <= HIGH_FREQ;
                end
                3'b100: begin
                    voltage_level <= HIGH_VOLTAGE;
                    frequency_level <= HIGH_FREQ;
                end
                3'b101: begin
                    voltage_level <= HIGH_VOLTAGE;
                    frequency_level <= MAX_FREQ;
                end
                3'b110: begin
                    voltage_level <= MAX_VOLTAGE;
                    frequency_level <= MAX_FREQ;
                end
                3'b111: begin
                    voltage_level <= MAX_VOLTAGE;
                    frequency_level <= MAX_FREQ; // Max settings
                end
                default: begin
                    voltage_level <= LOW_VOLTAGE;
                    frequency_level <= LOW_FREQ;
                end
            endcase
        end
    end
endmodule

