module uart_tx #(parameter BAUD_RATE = 9600) (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire send,  
    output reg tx,  
    output reg transmitting  
);  
    reg [3:0] bit_count;  
    reg [10:0] shift_reg;  
    reg [15:0] baud_counter;  
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;  
    reg [1:0] state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            tx <= 1;  
            transmitting <= 0;  
            state <= IDLE;  
            baud_counter <= 0;  
            bit_count <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send) begin  
                        shift_reg <= {1'b1, data_in, 1'b0}; // Stop bit, data, start bit  
                        bit_count <= 0;  
                        baud_counter <= 0;  
                        state <= START;  
                        transmitting <= 1;  
                    end  
                end  
                START: begin  
                    baud_counter <= baud_counter + 1;  
                    if (baud_counter >= (50000000 / BAUD_RATE) - 1) begin  
                        baud_counter <= 0;  
                        tx <= 0; // Start bit  
                        state <= DATA;  
                    end  
                end  
                DATA: begin  
                    baud_counter <= baud_counter + 1;  
                    if (baud_counter >= (50000000 / BAUD_RATE) - 1) begin  
                        baud_counter <= 0;  
                        tx <= shift_reg[bit_count + 1];  
                        bit_count <= bit_count + 1;  
                        if (bit_count == 7) begin  
                            state <= STOP;  
                        end  
                    end  
                end  
                STOP: begin  
                    baud_counter <= baud_counter + 1;  
                    if (baud_counter >= (50000000 / BAUD_RATE) - 1) begin  
                        baud_counter <= 0;  
                        tx <= 1; // Stop bit  
                        transmitting <= 0;  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

