module chebyshev_filter (  
    input clk,  
    input reset,  
    input [15:0] x_in,  
    output reg [15:0] y_out  
);  
    reg [15:0] delay [4:0]; // Delay elements for 5th order  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            for (i = 0; i < 5; i = i + 1)  
                delay[i] <= 16'b0;  
            y_out <= 16'b0;  
        end else begin  
            y_out <= x_in + delay[4] - (delay[3] >>> 1); // Simple Chebyshev equation  
            // Update delay elements  
            for (i = 4; i > 0; i = i - 1)  
                delay[i] <= delay[i-1];  
            delay[0] <= x_in;  
        end  
    end  
endmodule

module fifo_queue #(parameter DEPTH = 4, DATA_WIDTH = 8) (  
    input wire clk,  
    input wire reset,  
    input wire enqueue,  
    input wire dequeue,  
    input wire [DATA_WIDTH-1:0] data_in,  
    output reg [DATA_WIDTH-1:0] data_out,  
    output reg full,  
    output reg empty  
);  
    reg [DATA_WIDTH-1:0] queue [0:DEPTH-1];  
    reg [3:0] head;  
    reg [3:0] tail;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            head <= 0;  
            tail <= 0;  
            count <= 0;  
            full <= 0;  
            empty <= 1;  
        end else begin  
            if (enqueue && !full) begin  
                queue[tail] <= data_in;  
                tail <= (tail + 1) % DEPTH;  
                count <= count + 1;  
            end  
            if (dequeue && !empty) begin  
                data_out <= queue[head];  
                head <= (head + 1) % DEPTH;  
                count <= count - 1;  
            end  
            full <= (count == DEPTH);  
            empty <= (count == 0);  
        end  
    end  
endmodule

