module iir_filter (  
    input clk,  
    input rst,  
    input signed [15:0] x,  
    input signed [15:0] a,  
    output reg signed [15:0] y,  
    output reg signed [15:0] b  
);  
    reg signed [15:0] w1, w2;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            y <= 0;  
            b <= 0;  
            w1 <= 0;  
            w2 <= 0;  
        end else begin  
            w1 <= x + a * y;  
            w2 <= w1;  
            y <= w2;  
            b <= w1;  
        end  
    end  
endmodule

