module aes_256 (
    input clk,
    input rst,
    input [255:0] plaintext,
    input [255:0] key,
    output reg [255:0] ciphertext
);
    reg [2:0] state; // State for the AES rounds
    parameter IDLE = 3'b000, ROUND1 = 3'b001, ROUND2 = 3'b010, ROUND3 = 3'b011, FINAL = 3'b100;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            ciphertext <= 256'b0;
        end else begin
            case (state)
                IDLE: begin
                    ciphertext <= plaintext ^ key; // AddRoundKey
                    state <= ROUND1;
                end
                ROUND1: begin
                    // Simulate one round of AES operation
                    // For sake of the example, just XOR again
                    ciphertext <= ciphertext ^ key; 
                    state <= ROUND2;
                end
                ROUND2: begin
                    // Simulate another round of AES operation
                    ciphertext <= ciphertext ^ key; 
                    state <= ROUND3;
                end
                ROUND3: begin
                    // Final round
                    ciphertext <= ciphertext ^ key; 
                    state <= FINAL;
                end
                FINAL: begin
                    // Final output
                    state <= IDLE; // Reset to IDLE
                end
            endcase
        end
    end
endmodule

module timer(  
    input clk,  
    input rst,  
    output reg [15:0] count  
);  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            count <= 16'b0;  
        else if (count == 16'hFFFF)  
            count <= 16'b0;  
        else  
            count <= count + 1;  
    end  
endmodule

