module divider_8bit(  
    input wire clk,  
    input wire enable,  
    input wire [7:0] dividend,  
    input wire [7:0] divisor,  
    output reg [7:0] quotient,  
    output reg [7:0] remainder,  
    output reg done  
);  

    reg [7:0] temp_dividend;  
    reg [7:0] temp_quotient;  
    reg [3:0] count;  

    always @(posedge clk) begin  
        if (enable) begin  
            if (count < 8) begin  
                // Shift left quotient and bring down next bit of dividend  
                temp_quotient = {temp_quotient[6:0], dividend[7 - count]};  
                temp_dividend = {remainder, 1'b0};  
                remainder = temp_dividend - divisor;  
                if (!remainder[7]) begin  
                    // If remainder is positive, set the quotient bit  
                    temp_quotient[0] = 1;  
                end else begin  
                    // If remainder is negative, keep the quotient bit 0  
                    remainder = temp_dividend;  
                end  
                quotient = temp_quotient;  
                count = count + 1;  
            end else begin  
                done = 1;  
            end  
        end else begin  
            // Reset state  
            quotient = 0;  
            remainder = 0;  
            temp_quotient = 0;  
            temp_dividend = 0;  
            count = 0;  
            done = 0;  
        end  
    end  
endmodule

