module rng_lfsr(
    input clk,
    input reset,
    input [3:0] seed,
    output reg [3:0] random_out
);
    reg [3:0] lfsr;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lfsr <= seed; // Load seed value
        end else begin
            // LFSR feedback polynomial for 4-bit
            lfsr <= {lfsr[2:0], lfsr[3] ^ lfsr[2] ^ lfsr[1] ^ lfsr[0]};
        end
        random_out <= lfsr;
    end
endmodule

module d_latch (
    input wire D,
    input wire CLK,
    output reg Q
);
