module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire start_transmit,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 104; // Example for a 9600 baud with 100 MHz clock
    reg [6:0] bit_index;
    reg [7:0] data_buffer;
    reg [6:0] counter;
    reg transmitting;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1; // Idle state is high
            busy <= 0;
            transmitting <= 0;
            counter <= 0;
            bit_index <= 0;
        end else if (start_transmit && !busy) begin
            busy <= 1;
            data_buffer <= data_in;
            transmitting <= 1;
            tx <= 0; // Start bit
            bit_index <= 0;
            counter <= 0;
        end else if (transmitting) begin
            if (counter < BAUD_RATE_DIV) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                if (bit_index < 8) begin
                    tx <= data_buffer[bit_index]; // Send data bits
                    bit_index <= bit_index + 1;
                end else if (bit_index == 8) begin
                    tx <= 1; // Stop bit
                    bit_index <= bit_index + 1;
                end else begin
                    busy <= 0; // Transmission complete
                    transmitting <= 0;
                end
            end
        end
    end
endmodule

