    // Initialize
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
            done <= 0;
            decoded_bits <= 2'b00;
            path_metric[0] <= 4'b0000;
            path_metric[1] <= 4'b0000;
            path_metric[2] <= 4'b0000;
            path_metric[3] <= 4'b0000;
        end else if (valid) begin
            // Update path metrics based on input
