module binary_search(input [4:0] number, output reg found);  
  always @(*) begin  
    case (number)  
      5'b00001: found = 1;  
      5'b00010: found = 1;  
      5'b00011: found = 1;  
      5'b00100: found = 1;  
      5'b00101: found = 1;  
      default: found = 0;  
    endcase  
  end  
endmodule

module ECC_Point_Addition(
    input clk,
    input reset,
    input [7:0] x1,
    input [7:0] y1,
    input [7:0] x2,
    input [7:0] y2,
    output reg [7:0] x3,
    output reg [7:0] y3
);
    reg [7:0] lambda;
    reg [7:0] x3_temp;
    reg [7:0] y3_temp;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x3 <= 8'b0;
            y3 <= 8'b0;
        end else begin
            // Compute lambda (slope)
            lambda <= (y2 - y1) / (x2 - x1); // Assuming no division by zero for simplicity

            // Compute x3
            x3_temp <= lambda * lambda - x1 - x2;
            // Compute y3
            y3_temp <= lambda * (x1 - x3_temp) - y1;

            x3 <= x3_temp;
            y3 <= y3_temp;
        end
    end
endmodule

module deserializer_16bit(  
    input clk,  
    input reset,  
    input serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] count;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            parallel_out <= 16'b0;  
            count <= 4'b0;  
        end else if (count < 4'd16) begin  
            parallel_out <= {parallel_out[14:0], serial_in};  
            count <= count + 1;  
        end else begin  
            // do nothing, wait for reset  
        end  
    end  
endmodule

module rrt_nearest (
    input wire clk,
    input wire enable,
    input wire [7:0] current_x,
    input wire [7:0] current_y,
    input wire [7:0] target_x,
    input wire [7:0] target_y,
    output reg [7:0] nearest_x,
    output reg [7:0] nearest_y
);
    reg [7:0] tree_x [0:15];
    reg [7:0] tree_y [0:15];
    integer i;

    initial begin
        // Initialize tree nodes (can also be set dynamically)
        for (i = 0; i < 16; i = i + 1) begin
            tree_x[i] = 0;
            tree_y[i] = 0;
        end
    end

    always @(posedge clk) begin
        if (enable) begin
            // Find the nearest node in the tree to the target point
            nearest_x = tree_x[0];
            nearest_y = tree_y[0];
            for (i = 1; i < 16; i = i + 1) begin
                if ( ((tree_x[i] - target_x)**2 + (tree_y[i] - target_y)**2) <
                     ((nearest_x - target_x)**2 + (nearest_y - target_y)**2) ) begin
                    nearest_x = tree_x[i];
                    nearest_y = tree_y[i];
                end
            end

            // Add current position to the tree (simple addition)
            tree_x[i] = current_x;
            tree_y[i] = current_y;
        end
    end
endmodule

module traffic_light_fsm (
    input clk,
    input reset,
    output reg [1:0] light_state // 00: Red, 01: Green, 10: Yellow
);
    // State encoding
    parameter RED = 2'b00;
    parameter GREEN = 2'b01;
    parameter YELLOW = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= RED; // Initialize to red on reset
        else
            current_state <= next_state; // Move to the next state
    end

    always @(*) begin
        case (current_state)
            RED: next_state = GREEN;
            GREEN: next_state = YELLOW;
            YELLOW: next_state = RED;
            default: next_state = RED; // Default state
        endcase
    end

    always @(posedge clk) begin
        light_state <= current_state; // Update output based on current state
    end
endmodule

module sata_controller (  
    input wire clk,  
    input wire rst,  
    input wire send,  
    input wire receive,  
    output reg [1:0] state  
);  
    // State Encoding  
    localparam IDLE = 2'b00;  
    localparam SEND = 2'b01;  
    localparam RECEIVE = 2'b10;  

    // Sequential Logic  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send)  
                        state <= SEND;  
                    else if (receive)  
                        state <= RECEIVE;  
                end  
                SEND: begin  
                    if (!send)  
                        state <= IDLE;  
                end  
                RECEIVE: begin  
                    if (!receive)  
                        state <= IDLE;  
                end  
                default: begin  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

