        if (rst) begin
            counter <= 0;
            vco_out <= 0;
        end else begin
            freq_reg <= (1 << frequency_control); // Adjust frequency based on control input
            if (counter >= freq_reg) begin
                vco_out <= ~vco_out; // Toggle output
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

