module carrier_recovery(
    input clk,
    input reset,
    input signal_in, // sampled input signal
    output reg signal_out // synchronized output signal
);
    reg [3:0] phase_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            phase_counter <= 0;
            signal_out <= 0;
        end else begin
            // Simple phase detector logic
            if (signal_in) begin
                phase_counter <= phase_counter + 1;
            end else begin
                phase_counter <= phase_counter - 1;
            end

            // Output signal based on phase counter
            if (phase_counter > 4) begin
                signal_out <= 1;
            end else if (phase_counter < -4) begin
                signal_out <= 0;
            end
        end
    end
endmodule

