module chacha20 (  
    input wire clk,  
    input wire reset,  
    input wire [31:0] key,  
    input wire [31:0] nonce,  
    output reg [31:0] keystream  
);  

reg [31:0] state [0:15];  
integer i;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        // Initialize state with key and nonce  
        state[0] <= 32'h61707865; // "expa"  
        state[1] <= 32'h3320646e; // "nd 3"  
        state[2] <= 32'h79622d32; // "2-by"  
        state[3] <= key;  
        state[4] <= nonce;  
        // The rest of the state can be set or left as zero  
        for (i = 5; i < 16; i = i + 1)  
            state[i] <= 32'h0;  
    end else begin  
        // Simple mixing for keystream generation  
        keystream <= state[0] + state[1] + state[2] + state[3];  
        // Rotate and mix the state  
        state[0] <= {state[0][7:0], state[0][31:8]};  
        state[1] <= {state[1][15:0], state[1][31:16]};  
        state[2] <= {state[2][23:0], state[2][31:24]};  
        state[3] <= {state[3][31:0]};  
    end  
end  
endmodule

