module serializer_32bit(  
    input clk,  
    input reset,  
    input [31:0] data_in,  
    input load,  
    output reg serialized_out  
);  
    reg [31:0] shift_reg;  
    reg [4:0] bit_count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 32'b0;  
            bit_count <= 5'b0;  
            serialized_out <= 1'b0;  
        end else if (load) begin  
            shift_reg <= data_in;  
            bit_count <= 5'd31;  
        end else if (bit_count >= 0) begin  
            serialized_out <= shift_reg[bit_count];  
            bit_count <= bit_count - 1;  
        end  
    end  
endmodule

